    public static function retention(App $app,string $site,string $before,bool $replayOnly=false):array {$record=['id'=>Store::uuid(),'site_id'=>$site,'type'=>'retention','before'=>$before,'replay_only'=>$replayOnly,'created_at'=>Store::now()];self::appendJournal($app->config,[$record]);return self::applyRecord($app,$record);}
    public static function text(mixed $value,int $max=120):string {if(!is_string($value)||trim($value)===''||mb_strlen($value)>$max)Http::error(400,'invalid_request');return trim($value);}
    private static function sharePassword(string $password):string{return 'php-share-sha384:'.password_hash(base64_encode(hash('sha384',$password,true)),PASSWORD_DEFAULT);}
    private static function verifySharePassword(string $password,string $hash):bool{return str_starts_with($hash,'php-share-sha384:')?password_verify(base64_encode(hash('sha384',$password,true)),substr($hash,17)):password_verify($password,$hash);}
