        self::route($a,$router,'POST',$base.'/alerts/:id/silence',function(Http $r)use($a){$s=self::site($r);$a->auth->authorize($r,$s,'admin');$v=self::owned($a,'alert_rules',$r->params['id'],$s);$h=(int)($r->body['hours']??0);if($h<1||$h>720)Http::error(400,'hours_invalid');$v['silenced_until']=gmdate('c',time()+$h*3600);self::write($a,$s,'alert_rules',$v);return ['ok'=>true];});
        self::registerAccess($a,$router,$base);
        self::route($a,$router,'GET',$base.'/usage',function(Http $r)use($a){$s=self::site($r);$a->auth->authorize($r,$s);$row=$a->db->one("SELECT count(*) event_count,COALESCE(sum(octet_length(body)),0) bytes FROM documents WHERE kind='events' AND site_id=?",[$s]);return ['events'=>(int)$row['event_count'],'bytes'=>(int)$row['bytes'],'event_count'=>(int)$row['event_count'],'source'=>'mysql','coverage'=>1];});
        self::route($a,$router,'PATCH',$base.'/retention',function(Http $r)use($a){$s=self::site($r);$a->auth->authorize($r,$s,'admin');$days=$r->body['days']??null;if(!is_int($days)||$days<1||$days>3650)Http::error(400,'retention_invalid');$a->db->transaction(function()use($a,$s,$days){$a->db->lock('site:'.$s);$v=$a->store->get('sites',$s);$v['retention_days']=$days;$a->store->put('sites',$s,$v,$s);});return ['ok'=>true];});
        self::route($a,$router,'POST',$base.'/delete-visitor',function(Http $r)use($a){$s=self::site($r);$u=$a->auth->authorize($r,$s,'admin');return self::deleteVisitor($a,$s,$r->body,$u['id']);});
        self::route($a,$router,'POST',$base.'/exports',function(Http $r)use($a){$s=self::site($r);$u=$a->auth->authorize($r,$s,'admin');$format=$r->body['format']??'csv';if(!in_array($format,['csv','json'],true))Http::error(400,'export_format_invalid');$v=['id'=>Store::uuid(),'site_id'=>$s,'actor_id'=>$u['id'],'format'=>$format,'full_export'=>(bool)($r->body['full']??false),'status'=>'pending','created_at'=>Store::now()];self::write($a,$s,'export_jobs',$v);return ['id'=>$v['id'],'status'=>'pending'];});
        self::route($a,$router,'GET',$base.'/exports/:id',function(Http $r)use($a){$s=self::site($r);$a->auth->authorize($r,$s,'admin');$v=self::owned($a,'export_jobs',$r->params['id'],$s);if(($v['status']??'')!=='complete'||!is_file($v['path']??''))Http::error(409,'export_not_ready');header('Content-Type: '.($v['format']==='json'?'application/json':'text/csv; charset=utf-8'));header('Content-Disposition: attachment; filename="baize-'.$v['id'].'.'.$v['format'].'"');readfile($v['path']);return null;});
    }
    public static function write(App $a,string $s,string $kind,array $v):void {$a->db->transaction(function()use($a,$s,$kind,$v){$a->db->lock('site:'.$s);$a->store->put($kind,$v['id'],$v,$s);});}
    public static function dsl(mixed $v):array {if(!is_array($v))Http::error(400,'report_dsl_invalid');foreach(['from','to'] as $key)if(!is_string($v[$key]??null)||strtotime($v[$key])===false)Http::error(400,'report_range_invalid');if(strtotime($v['from'])>=strtotime($v['to']))Http::error(400,'report_range_invalid');return $v;}
    private static function registerAccess(App $a,Router $r,string $base):void
    {
        self::route($a,$r,'GET','/embed/chart',function(Http $h)use($a){$share=null;$token=(string)($h->query['token']??'');foreach($a->store->list('share_links') as $v)if(hash_equals((string)($v['token_hash']??''),Security::hashToken($token)))$share=$v;if(!$share||($share['revoked']??false)||(isset($share['expires_at'])&&strtotime($share['expires_at'])<=time())||(($share['password_hash']??null)&&!self::verifySharePassword($h->header('x-share-password')??'',$share['password_hash'])))Http::error(403,'share_unavailable');$nonce=base64_encode(random_bytes(18));$origins=$share['frame_origins']??[];header("Content-Security-Policy: default-src 'none'; style-src 'nonce-".$nonce."'; frame-ancestors ".($origins?implode(' ',$origins):"'none'"));header('Referrer-Policy: no-referrer');header('Cache-Control: no-store');header('Content-Type: text/html; charset=utf-8');$stats=Analytics::stats($a,$share['site_id'],['from'=>gmdate('c',time()-30*86400),'to'=>Store::now()]);$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$english=($h->query['lang']??'zh-CN')==='en';$title=$english?'Top pages (last 30 days)':'热门页面（最近30天）';$rows=array_slice($stats['pages']??[],0,10);$max=max(array_merge([1],array_column($rows,'pv')));echo '<!doctype html><html lang="'.($english?'en':'zh-CN').'"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'.$title.'</title><style nonce="'.$nonce.'">body{font-family:system-ui;color:#172033;background:white;padding:16px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:8px;border-bottom:1px solid #ddd}td:first-child{overflow-wrap:anywhere}progress{width:100%;accent-color:#1670bd}</style><h2>'.$title.'</h2><table><thead><tr><th>'.($english?'Page':'页面').'</th><th>'.($english?'Page views':'浏览量').'</th><th>'.($english?'Ratio':'比例').'</th></tr></thead><tbody>';foreach($rows as $row)echo '<tr><td>'.$esc($row['path']).'</td><td>'.(int)$row['pv'].'</td><td><progress max="'.$max.'" value="'.(int)$row['pv'].'"></progress></td></tr>';echo '</tbody></table><p>'.($english?'Source: MySQL':'来源：MySQL').'</p>';if(!$rows)echo '<p>'.($english?'No visit data':'暂无访问数据').'</p>';if(($stats['coverage']??0)!==1)echo '<p>'.($english?'Some requested intervals are unavailable.':'部分请求区间不可用，图表仅包含可用部分。').'</p>';echo '</html>';return null;});
        self::route($a,$r,'POST',$base.'/tokens',function(Http $h)use($a){$s=self::site($h);$u=$a->auth->authorize($h,$s,'admin');$scopes=$h->body['scopes']??[];if(isset($h->body['expires_at']))self::instant($h->body['expires_at']);if(!is_array($scopes)||!$scopes||array_diff($scopes,['read','write','admin']))Http::error(400,'token_scopes_invalid');$token=bin2hex(random_bytes(32));$v=['id'=>Store::uuid(),'site_id'=>$s,'user_id'=>$u['id'],'scopes'=>$scopes,'token_hash'=>Security::hashToken($token),'expires_at'=>$h->body['expires_at']??null,'revoked'=>false];self::write($a,$s,'api_tokens',$v);return ['id'=>$v['id'],'token'=>$token];});
        foreach(['tokens'=>'api_tokens','shares'=>'share_links'] as $path=>$kind)self::route($a,$r,'DELETE',$base.'/'.$path.'/:id',function(Http $h)use($a,$kind){$s=self::site($h);$a->auth->authorize($h,$s,'admin');$v=self::owned($a,$kind,$h->params['id'],$s);$v['revoked']=true;self::write($a,$s,$kind,$v);return ['ok'=>true];});
        self::route($a,$r,'POST',$base.'/shares',function(Http $h)use($a){$s=self::site($h);$a->auth->authorize($h,$s,'admin');$b=$h->body;if(isset($b['expires_at']))self::instant($b['expires_at']);$origins=$b['frame_origins']??[];if(!is_array($origins)||count($origins)>20)Http::error(400,'frame_origin_invalid');foreach($origins as $origin)if(!is_string($origin)||Outbound::origin($origin)!==$origin||!in_array(parse_url($origin,PHP_URL_SCHEME),['https','http'],true))Http::error(400,'frame_origin_invalid');if(isset($b['password'])&&(strlen($b['password'])<8||strlen($b['password'])>1024))Http::error(400,'share_password_invalid');$token=bin2hex(random_bytes(24));$v=['id'=>Store::uuid(),'site_id'=>$s,'token_hash'=>Security::hashToken($token),'password_hash'=>isset($b['password'])?self::sharePassword($b['password']):null,'expires_at'=>$b['expires_at']??null,'frame_origins'=>$origins,'revoked'=>false];self::write($a,$s,'share_links',$v);return ['id'=>$v['id'],'token'=>$token,'url'=>rtrim($a->config['public_url'],'/').'/share/'.$token];});
        self::route($a,$r,'POST','/api/v1/shares/:token',function(Http $h)use($a){$share=null;foreach($a->store->list('share_links') as $v)if(hash_equals((string)($v['token_hash']??''),Security::hashToken($h->params['token'])))$share=$v;if(!$share||($share['revoked']??false)||(isset($share['expires_at'])&&strtotime($share['expires_at'])<=time())||(($share['password_hash']??null)&&!self::verifySharePassword((string)($h->body['password']??''),$share['password_hash'])))Http::error(403,'share_unavailable');$site=$a->store->get('sites',$share['site_id']);$to=Store::now();$from=gmdate('c',time()-30*86400);$stats=Analytics::stats($a,$share['site_id'],['from'=>$from,'to'=>$to]);header('Cache-Control: no-store');return ['site_name'=>$site['name'],'days'=>$stats['trend']??[],'range'=>['from'=>$from,'to'=>$to],'privacy'=>($site['privacy_mode']??'standard'),'storage'=>['rollups'=>'mysql'],'coverage'=>1];});
        self::route($a,$r,'GET',$base.'/members',function(Http $h)use($a){$s=self::site($h);$a->auth->authorize($h,$s,'admin');$out=[];foreach($a->store->list('site_members',$s) as $m){$u=$a->store->get('users',$m['user_id']);if($u)$out[]=['id'=>$u['id'],'email'=>$u['email'],'name'=>$u['name'],'role'=>$m['role']];}return $out;});
        foreach(['PATCH','DELETE'] as $method)self::route($a,$r,$method,$base.'/members/:userId',function(Http $h)use($a,$method){$s=self::site($h);$a->auth->authorize($h,$s,'admin');return $a->db->transaction(function()use($a,$h,$s,$method){$a->db->lock('site:'.$s);foreach($a->db->all("SELECT id,body FROM documents WHERE kind='site_members' AND site_id=?",[$s]) as $row){$m=json_decode($row['body'],true,512,JSON_THROW_ON_ERROR);if($m['user_id']!==$h->params['userId'])continue;if($m['role']==='owner')Http::error(400,'owner_protected');if($method==='DELETE')$a->store->delete('site_members',$row['id']);else{if(!in_array($h->body['role']??'',['admin','analyst','viewer'],true))Http::error(400,'role_invalid');$m['role']=$h->body['role'];$a->store->put('site_members',$row['id'],$m,$s);}}return ['ok'=>true];});});
        self::route($a,$r,'POST',$base.'/invites',function(Http $h)use($a){$s=self::site($h);$a->auth->authorize($h,$s,'admin');return $a->db->transaction(function()use($a,$h,$s){$a->db->lock('site:'.$s);$email=strtolower((string)($h->body['email']??''));$role=$h->body['role']??'viewer';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['admin','analyst','viewer'],true))Http::error(400,'invite_invalid');$channel=null;foreach($a->store->list('notification_channels',$s) as $c)if($c['kind']==='smtp'&&(!isset($h->body['channel_id'])||$h->body['channel_id']===$c['id'])){$channel=$c;break;}if(isset($h->body['channel_id'])&&!$channel)Http::error(400,'smtp_channel_unavailable');$token=Security::randomToken();$v=['id'=>Store::uuid(),'site_id'=>$s,'email'=>$email,'role'=>$role,'token_hash'=>Security::hashToken($token),'expires_at'=>gmdate('c',time()+604800),'accepted_at'=>null];$a->store->put('site_invites',$v['id'],$v,$s);$url=rtrim($a->config['public_url'],'/').'/invite/'.$token;if($channel)Operations::enqueueNotification($a,$s,$channel['id'],['title'=>'白泽团队邀请','recipient'=>$email,'invitation_url'=>$url,'role'=>$role],'invite:'.$v['id']);return ['id'=>$v['id'],'token'=>$token,'url'=>$url,'email_queued'=>$channel!==null];});});
        foreach(['accept','register'] as $mode)self::route($a,$r,'POST','/api/v1/invites/:token/'.$mode,function(Http $h)use($a,$mode){return $a->db->transaction(function()use($a,$h,$mode){$a->db->lock('invite:'.Security::hashToken($h->params['token']));$invite=null;foreach($a->store->list('site_invites') as $v)if(hash_equals((string)($v['token_hash']??''),Security::hashToken($h->params['token'])))$invite=$v;if(!$invite||$invite['accepted_at']||strtotime($invite['expires_at'])<=time())Http::error(403,'invitation_unavailable');$a->db->lock('site:'.$invite['site_id']);if($mode==='accept'){$u=$a->auth->user($h);if(strtolower($u['email'])!==$invite['email'])Http::error(403,'invitation_denied');}else{$password=(string)($h->body['password']??'');Security::validatePassword($password);$a->db->lock('users:email:'.$invite['email']);foreach($a->store->list('users') as $existing)if(strtolower($existing['email'])===$invite['email'])Http::error(409,'invite_login_required');$u=['id'=>Store::uuid(),'email'=>$invite['email'],'name'=>self::text($h->body['name']??null,100),'password_hash'=>Security::password($password),'is_admin'=>false];$a->store->put('users',$u['id'],$u);}$id=$invite['site_id'].':'.$u['id'];$old=$a->store->get('site_members',$id);$m=['id'=>$id,'site_id'=>$invite['site_id'],'user_id'=>$u['id'],'role'=>($old['role']??'')==='owner'?'owner':$invite['role']];$a->store->put('site_members',$id,$m,$invite['site_id']);$invite['accepted_at']=Store::now();$a->store->put('site_invites',$invite['id'],$invite,$invite['site_id']);return ['ok'=>true,'email'=>$u['email']];});});
    }
}
